-- =====================================================================
-- Kanban SCIH — carga da reorganização V7.2 (HGNI), aprovada pela
-- coordenação em 27/10/2026. Fonte: KANBAN_SCIH_HGNI_TAREFAS_POR_FUNCIONARIO_V7_2.xlsx
--
-- 1) Funções e escala da equipe (Camila e Cristiane em regime de plantão;
--    as datas dos plantões são cadastradas no Kanban quando a escala sair).
-- 2) Tarefas anteriores do HGNI ARQUIVADAS (ativo = false), não apagadas.
-- 3) 81 tarefas da V7.2 (uma por cartão da planilha).
-- O estado anterior da escala e das tarefas fica em
-- public.correcoes_qualidade_dado, lote 'kanban_v72_hgni_2026-10-27'.
-- Pode ser executada de novo sem duplicar.
-- =====================================================================

DO $$
DECLARE n int; d int;
BEGIN
  WITH _v72_usuarios AS (
  SELECT pe.*, hu.hospital_id, hu.user_id
  FROM (VALUES
    ('lucas', 'Lucas da Silva Lemos%', 'Enfermeiro – coordenador do SCIH', 'fixo', ARRAY[1,2,3,4,5]::smallint[], 'Aprova, assina e envia (Anvisa, DDD, BI, higiene das mãos, ata); publica o ciclo da Camila e os plantões; reunião da CCIH; round da infectologista; divisão mensal; PCIRAS e protocolos; encerra ações intersetoriais.'),
    ('mara', 'Mara Rubia%', 'Enfermeira de rotina geral', 'fixo', ARRAY[1,2,3,4,5]::smallint[], 'Vigilância das enfermarias (Clínica Médica, Enfermaria pediátrica, Clínicas Cirúrgicas 1 e 2) e da Emergência pediátrica, incluindo estrutura; validação diária (CTIs: só urgências); quarta sem a Camila: alertas críticos; triagem microbiológica mínima (seg e qua); filas dos plantões; não conformidades, porta de entrada, surtos, água e fechamento mensal.'),
    ('cristiane', 'Cristiane Pio%', 'Enfermeira plantonista – 2 plantões de 12 h/semana', 'plantao', ARRAY[0,1,2,3,4,5,6]::smallint[], 'Vigilância dos CTIs (revisão de critérios e validação dos casos) e auditoria de estrutura dos CTIs nos plantões; consolida a estrutura do hospital; coordenação técnica da vigilância de ISC; higiene das mãos nos plantões; planeja o calendário de treinamentos.'),
    ('oseas', 'Oseas%', 'Enfermeiro de rotina – higiene e limpeza', 'fixo', ARRAY[1,2,3,4,5]::smallint[], 'Função protegida: auditoria de limpeza concorrente e terminal, dispensers, lixeiras e ambiente; treinamento e não conformidades da limpeza; controle de pragas (até o 5º dia útil) e caixa d''água (a cada 5 meses); apoio logístico à coleta de água.'),
    ('valeria', 'Valeria%', 'Bióloga', 'fixo', ARRAY[2,4,5]::smallint[], 'Revisão microbiológica e alertas; mapa de precauções (versão do fim de semana na sexta); PLACON RJ (10º dia útil); microrganismos e resistência à Anvisa; painel mensal; relatório semestral (junho e dezembro).'),
    ('administrativo', 'Lorraine%', 'Apoio administrativo', 'fixo', ARRAY[1,2,3,4,5]::smallint[], 'Altas e movimentações; exames e lista de alertas até 10h30; planilha de cirurgias, Ficha NISS e cirurgias contaminadas; busca telefônica pós-alta (executor único); dados de DDD e BI; atas, documentos e prazos. Não interpreta nem valida.'),
    ('danubia', 'Danubia%', 'Técnica de enfermagem – CTI 1, CTI 2 e CTI 3 (técnica única às quintas)', 'fixo', ARRAY[1,4,5]::smallint[], 'Fichas e IRASControl dos CTIs 1, 2 e 3, auditorias de processos e de higiene das mãos nos CTIs; transversal: qualidade dos registros e denominadores de UTI. Na quinta cobre os alertas críticos da área da Rosângela.'),
    ('rosangela', 'Rosangela%', 'Técnica de enfermagem – trauma e emergência adulto (técnica única às terças)', 'fixo', ARRAY[1,2,5]::smallint[], 'Busca ativa e IRASControl de Trauma clínico (e externo), UPO, Trauma cirúrgico, Nova emergência e PCR; transversal: precauções no leito e higiene das mãos (método e consolidação). Na terça cobre os alertas críticos dos CTIs.'),
    ('camila', 'Camila%', 'Técnica de enfermagem plantonista – 12x60 (7h–19h)', 'plantao', ARRAY[0,1,2,3,4,5,6]::smallint[], 'Técnica plantonista sem carteira fixa: apoio fixo à vigilância e às auditorias do Trauma clínico; cobre a área sem titular no dia (ter: CTIs; qua: CTIs e área da Rosângela; qui: área da Rosângela); auditorias rotativas das enfermarias, Emergência pediátrica e centro cirúrgico; estrutura do trauma e da emergência adulto; higiene das mãos na troca de turno; fim de semana: vigilância crítica.')
  ) AS pe(chave, padrao, funcao, regime, dias, atribuicoes)
  JOIN public.hospitals h ON h.name = 'Hospital Geral de Nova Iguaçu'
  JOIN public.hospital_users hu ON hu.hospital_id = h.id
  JOIN public.profiles p ON p.user_id = hu.user_id AND p.full_name ILIKE pe.padrao
)
  SELECT count(*), count(DISTINCT chave) INTO n, d FROM _v72_usuarios;
  IF n <> 9 OR d <> 9 THEN
    RAISE EXCEPTION 'Equipe V7.2: esperado 1 usuário por pessoa (9), encontrado % linhas / % pessoas', n, d;
  END IF;
END $$;

