INSERT INTO public.correcoes_qualidade_dado (lote, tabela, registro_id, acao, motivo, estado_anterior, estado_novo, executado_por)
SELECT 'kanban_v72_hgni_2026-10-27', 'public.kanban_ccih_escala', e.id, 'atualizado', 'Funções e escala da reorganização V7.2',
       jsonb_build_object('dias_semana', e.dias_semana, 'regime', e.regime, 'funcao', e.funcao),
       jsonb_build_object('dias_semana', u.dias, 'regime', u.regime, 'funcao', u.funcao),
       'claude_code (aprovado pelo usuário)'
FROM public.kanban_ccih_escala e
JOIN _v72_usuarios u ON u.hospital_id = e.hospital_id AND u.user_id = e.user_id
WHERE (e.dias_semana, e.regime, coalesce(e.funcao, '')) IS DISTINCT FROM (u.dias, u.regime, u.funcao);

