INSERT INTO public.kanban_ccih_escala (hospital_id, user_id, dias_semana, regime, funcao, atribuicoes, updated_at)
SELECT hospital_id, user_id, dias, regime, funcao, atribuicoes, now() FROM _v72_usuarios
ON CONFLICT (hospital_id, user_id) DO UPDATE
SET dias_semana = EXCLUDED.dias_semana, regime = EXCLUDED.regime, funcao = EXCLUDED.funcao,
    atribuicoes = EXCLUDED.atribuicoes, updated_at = now();

-- ── 2) Arquiva as tarefas anteriores ──────────────────────────────────
INSERT INTO public.correcoes_qualidade_dado (lote, tabela, registro_id, acao, motivo, estado_anterior, estado_novo, executado_por)
SELECT 'kanban_v72_hgni_2026-10-27', 'public.kanban_ccih_tarefas', t.id, 'desativado', 'Kanban substituído pela reorganização V7.2',
       to_jsonb(t), jsonb_build_object('ativo', false), 'claude_code (aprovado pelo usuário)'
FROM public.kanban_ccih_tarefas t
JOIN public.hospitals h ON h.id = t.hospital_id AND h.name = 'Hospital Geral de Nova Iguaçu'
WHERE t.ativo AND t.versao IS DISTINCT FROM 'V7.2';

UPDATE public.kanban_ccih_tarefas t SET ativo = false, versao = coalesce(t.versao, 'anterior à V7.2')
FROM public.hospitals h
WHERE h.id = t.hospital_id AND h.name = 'Hospital Geral de Nova Iguaçu'
  AND t.ativo AND t.versao IS DISTINCT FROM 'V7.2';

