INSERT INTO public.kanban_ccih_tarefas (
  hospital_id, title, description, assigned_to, assigned_to_ids, assigned_by, recurrence, status, priority,
  quando, validador, backup, tipo, alteracao, horario, tempo_alvo, dias_semana, dias_mes, no_plantao,
  setores, versao, ordem, ativo, source)
SELECT u.hospital_id, c.title, c.description, u.user_id, ARRAY[u.user_id], coord.user_id, c.recurrence, 'in_progress', c.priority,
       c.quando, c.validador, c.backup, c.tipo, c.alteracao, c.horario, c.tempo_alvo, c.dias_semana, c.dias_mes, c.no_plantao,
       c.setores, 'V7.2', c.ordem, true, 'ccih'
FROM (VALUES
    (1, 'danubia', 'Fichas e IRASControl – CTI 1, CTI 2 e CTI 3', 'Preencher a ficha de vigilância de cada paciente dos três CTIs e alimentar o IRASControl: admissões, saídas, dispositivos (VM, CVC, SVD) com datas de inserção e retirada, exames, antimicrobianos, critérios de IRAS e pendências. Começar pela passagem escrita de terça (Rosângela) e de quarta (Camila, se de plantão, ou Mara Rubia) e pela passagem formal dos plantões da Cristiane. Encaminhar suspeitas à validação (Cristiane nos plantões; urgências a Mara Rubia). Entrega: registros dos três CTIs atualizados ao fim de cada dia de presença.', 'Segunda, quinta e sexta', 'high', 'Cristiane (plantões); Mara Rubia entre plantões', 'Rosângela (ter): alertas críticos; Camila (plantão): fichas completas', 'Carteira', 'V7.2: Danúbia dedica-se apenas aos CTIs (a Clínica Médica passa à Mara Rubia); validação dos CTIs pela Cristiane nos plantões.', 'Seg 08:40–12:00; Seg 13:00–14:30; Qui 08:00–11:30; Qui 13:00–14:15; Sex 08:00–11:30', '13 h 05/semana', 'daily', ARRAY[1,4,5]::smallint[], NULL, false, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (2, 'danubia', 'Denominadores mensais de UTI – CTI 1, CTI 2 e CTI 3', 'Antes do fechamento, conferir paciente-dia e dispositivo-dia dos três CTIs no IRASControl contra o censo (MV) e sinalizar divergências a Mara Rubia e à Cristiane.', 'Mensal (1º ao 3º dia útil)', 'high', 'Mara Rubia', 'Mara Rubia', 'Transversal', 'Mantido.', 'Sem bloco fixo', 'Mensal: 1 h (1º ao 3º dia útil)', 'monthly', NULL, NULL, false, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (3, 'danubia', 'Auditoria de processos no leito – CTI 1, CTI 2 e CTI 3', 'Checklist padronizado à beira do leito, aplicado a todos os pacientes com dispositivo presentes no momento da auditoria, conforme protocolos institucionais: bundle de cateter venoso central (inserção, manutenção, curativo e data), prevenção de pneumonia associada à ventilação (cabeceira, higiene oral, circuito), sonda vesical (sistema fechado, posição da bolsa, fixação), identificação e datas dos dispositivos, curativos, precauções e coleta de hemocultura/swab quando observada. Registrar não conformidade com responsável do setor e evidência esperada; devolutiva ao enfermeiro do setor no mesmo dia.', 'Semanal, um CTI por dia: segunda CTI 3, quinta CTI 1, sexta CTI 2', 'normal', 'Mara Rubia', 'Camila (plantão)', 'Carteira', 'Mantido (V7.1).', 'Seg 14:30–15:15; Qui 15:00–15:45; Sex 13:00–13:45', '2 h 15/semana', 'daily', ARRAY[1,4,5]::smallint[], NULL, false, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (4, 'danubia', 'Auditoria de higiene das mãos – CTI 1, CTI 2 e CTI 3', 'Sessão de observação direta de 20 minutos (±10), pelos 5 momentos da OMS: registrar categoria profissional, oportunidade, indicação e ação (fricção, lavagem ou não realizada), sem identificação nominal. Devolutiva imediata à equipe ao fim da sessão. Entregar o formulário a Rosângela para consolidação.', 'Semanal: 1 sessão por CTI (segunda CTI 1 e CTI 2; quinta CTI 3)', 'normal', 'Mara Rubia', 'Cristiane (plantão)', 'Carteira', 'Mantido (V7.1).', 'Seg 15:15–16:00; Qui 15:45–16:15', '1 h 15/semana', 'daily', ARRAY[1,4]::smallint[], NULL, false, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (5, 'danubia', 'Devolutiva da validação dos CTIs e correção das fichas', 'Ler a passagem formal dos plantões da Cristiane (casos validados, descartados e pendentes nos três CTIs) e os achados de estrutura; corrigir fichas e IRASControl e devolver as pendências à Cristiane (próximo plantão) ou a Mara Rubia (urgências).', 'Semanal, sexta-feira (e quinta, após plantão da Cristiane)', 'high', 'Cristiane', 'Mara Rubia', 'Transversal', 'NOVO V7.2: integra a técnica dos CTIs à vigilância da Cristiane.', 'Sex 11:30–12:00; Sex 14:45–15:15', '1 h/semana', 'daily', ARRAY[5]::smallint[], NULL, false, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (6, 'danubia', 'Consolidar pendências de atualização dos registros', 'Transversal – qualidade dos registros. Conferir registros elegíveis, pendências e divergências informadas pelas técnicas, pela Camila nos plantões, pela Mara Rubia (enfermarias e Emergência pediátrica) e pela validação da Cristiane. Entrega: lista semanal para validação.', 'Semanal, sexta-feira', 'normal', 'Mara Rubia', 'Rosângela', 'Transversal', 'Mantido.', 'Sex 13:45–14:45', '1 h/semana', 'daily', ARRAY[5]::smallint[], NULL, false, '{}'::text[]),
    (7, 'danubia', 'Cobertura de alertas críticos (quinta) – Trauma clínico, externo, UPO, Trauma cirúrgico, Nova emergência e PCR', 'Quinta-feira, única técnica fixa do dia: revisar SOMENTE a lista de alertas críticos das áreas da Rosângela, registrar a conduta e deixar passagem escrita. Se a Camila estiver de plantão, ela faz a busca ativa dessas áreas e Danúbia apenas confere a 2ª janela.', 'Quinta-feira', 'high', 'Mara Rubia', 'Camila (se de plantão)', 'Cobertura', 'V7.2: área coberta inclui Trauma cirúrgico e NE, agora da Rosângela; Emergência pediátrica sai (Mara Rubia).', 'Qui 11:30–12:00; Qui 14:15–15:00', '1 h 15/semana', 'daily', ARRAY[4]::smallint[], NULL, false, ARRAY['UPO','Trauma Clínico','Trauma Clínico Externo','Trauma Cirúrgico','Nova Emergência','PCR']::text[]),
    (8, 'rosangela', 'Busca ativa e IRASControl – Trauma clínico, externo e UPO', 'Revisar pacientes internos e os cerca de 3 externos definidos, admissões, saídas, dispositivos, exames e critérios de vigilância; atualizar o IRASControl. A UPO tem a maior rotatividade da área crítica (121 admissões em julho/2026): priorizar admissões e saídas; sinais de ISC na UPO vão à fila de ISC da Cristiane. No Trauma clínico, ler a passagem da Camila (apoio em todo plantão) e não duplicar o que ela já registrou.', 'Segunda, terça e sexta', 'high', 'Mara Rubia', 'Danúbia (qui) e Mara Rubia (qua): alertas críticos; Camila (plantão)', 'Carteira', 'V7.2: Camila apoia o Trauma clínico em todo plantão.', 'Seg 08:40–10:30; Ter 08:00–10:00; Sex 08:00–10:00', '5 h 50/semana', 'daily', ARRAY[1,2,5]::smallint[], NULL, false, ARRAY['UPO','Trauma Clínico','Trauma Clínico Externo']::text[]),
    (9, 'rosangela', 'Busca ativa e IRASControl – Trauma cirúrgico, Nova emergência e PCR', 'Revisar admissões, pacientes, dispositivos, exames e critérios de vigilância no Trauma cirúrgico e na Nova emergência; no PCR, triagem por risco, alertas e precauções. Atualizar o IRASControl e encaminhar suspeitas; sinais de ISC no Trauma cirúrgico vão à fila da Cristiane. Se o ''trauma cirúrgico externo'' for confirmado como grupo distinto, a lista nominal entra nesta carteira.', 'Segunda, terça e sexta', 'high', 'Mara Rubia', 'Danúbia (qui) e Mara Rubia (qua): alertas críticos; Camila (plantão)', 'Carteira', 'NOVO V7.2: Trauma cirúrgico e Nova emergência saem da Camila (sem dia fixo); Emergência pediátrica sai para a Mara Rubia.', 'Seg 10:30–12:00; Seg 13:00–13:45; Ter 10:00–11:15; Ter 13:00–14:15; Sex 10:00–11:30', '6 h 15/semana', 'daily', ARRAY[1,2,5]::smallint[], NULL, false, ARRAY['Trauma Cirúrgico','Nova Emergência','PCR']::text[]),
    (10, 'rosangela', 'Auditoria de processos no leito – UPO e Trauma cirúrgico', 'Checklist padronizado à beira do leito, aplicado a todos os pacientes com dispositivo presentes no momento da auditoria, conforme protocolos institucionais: bundle de cateter venoso central (inserção, manutenção, curativo e data), prevenção de pneumonia associada à ventilação (cabeceira, higiene oral, circuito), sonda vesical (sistema fechado, posição da bolsa, fixação), identificação e datas dos dispositivos, curativos, precauções e coleta de hemocultura/swab quando observada. Registrar não conformidade com responsável do setor e evidência esperada; devolutiva ao enfermeiro do setor no mesmo dia.', 'Semanal: segunda Trauma cirúrgico; terça UPO', 'normal', 'Mara Rubia', 'Camila (plantão)', 'Carteira', 'V7.2: o Trauma clínico passa à Camila (todo plantão); entra o Trauma cirúrgico.', 'Seg 13:45–14:30; Ter 15:30–16:15', '1 h 30/semana', 'daily', ARRAY[1,2]::smallint[], NULL, false, ARRAY['UPO','Trauma Cirúrgico']::text[]),
    (11, 'rosangela', 'Auditoria de higiene das mãos – UPO, Trauma clínico e Trauma cirúrgico', 'Sessão de observação direta de 20 minutos (±10), pelos 5 momentos da OMS: registrar categoria profissional, oportunidade, indicação e ação (fricção, lavagem ou não realizada), sem identificação nominal. Devolutiva imediata à equipe ao fim da sessão. Entregar o formulário a Rosângela para consolidação.', 'Semanal: 1 sessão por setor (segunda)', 'normal', 'Mara Rubia', 'Camila (plantão)', 'Carteira', 'V7.2: inclui o Trauma cirúrgico.', 'Seg 14:30–15:30', '1 h/semana', 'daily', ARRAY[1]::smallint[], NULL, false, ARRAY['UPO','Trauma Clínico','Trauma Cirúrgico']::text[]),
    (12, 'rosangela', 'Auditorias na Nova emergência e no PCR – processos e higiene das mãos', 'Rotativas na sexta: Nova emergência quinzenal (alternando processos no leito e sessão de higiene das mãos); PCR mensal. Sessão de observação direta de 20 minutos (±10), pelos 5 momentos da OMS: registrar categoria profissional, oportunidade, indicação e ação (fricção, lavagem ou não realizada), sem identificação nominal. Processos: pacientes com dispositivo, pelo checklist padronizado.', 'Rotativa: NE quinzenal; PCR mensal (sexta)', 'normal', 'Mara Rubia', 'Camila (plantão)', 'Carteira', 'V7.2: Emergência e Enfermaria pediátrica passam às auditorias da Camila; entra a Nova emergência.', 'Sex 13:00–13:45', '45 min/semana', 'daily', ARRAY[5]::smallint[], NULL, false, ARRAY['Nova Emergência','PCR']::text[]),
    (13, 'rosangela', 'Conferência do mapa de precauções no leito', 'Transversal – precauções. Nos próprios setores em todo comparecimento; nos demais, por amostra semanal priorizando pacientes recém-incluídos no mapa. Comparar mapa, indicação validada, sinalização, EPI e situação real; informar divergência imediatamente e consolidar na sexta. Terça: conferência com a Valéria.', 'Segunda, terça e sexta; consolidação na sexta', 'high', 'Valéria (microbiologia) e Mara Rubia (indicação)', 'Camila (plantão)', 'Transversal', 'Mantido.', 'Seg 15:30–16:00; Ter 15:00–15:30; Sex 11:30–12:00; Sex 14:45–15:15', '2 h/semana', 'daily', ARRAY[1,2,5]::smallint[], NULL, false, '{}'::text[]),
    (14, 'rosangela', 'Coordenar método e consolidar higiene das mãos', 'Transversal – higiene das mãos. Montar o plano amostral mensal por setor (setores fechados semanal pelas titulares e pela Camila no Trauma clínico; enfermarias, Emergência pediátrica e centro cirúrgico pela Camila nos plantões; Nova emergência e PCR por ela; troca de turno pela Camila; plantões pela Cristiane), calibrar as observadoras, analisar às sextas, consolidar por setor e categoria profissional e preparar a devolutiva e a planilha que o coordenador envia à Qualidade até o 10º dia útil. Para comparar períodos, dimensionar o número de oportunidades (referência OMS: 140 por medição para detectar diferença de 40% para 60%); abaixo disso, relatar como amostra insuficiente.', 'Análise semanal (sexta); consolidação mensal', 'normal', 'Mara Rubia', 'Danúbia', 'Transversal', 'V7.2: incorpora as sessões da Camila (plantões e troca de turno).', 'Sex 13:45–14:45', '1 h/semana', 'daily', ARRAY[5]::smallint[], NULL, false, '{}'::text[]),
    (15, 'rosangela', 'Cobertura de alertas críticos (terça) – CTI 1, CTI 2 e CTI 3', 'Terça-feira, única técnica fixa: revisar SOMENTE a lista de alertas críticos dos três CTIs (Danúbia ausente), registrar a conduta e deixar passagem escrita. Não preencher fichas. Se a Camila estiver de plantão, ela faz as fichas dos CTIs e Rosângela fica só na própria carteira.', 'Terça-feira', 'high', 'Mara Rubia', 'Camila (se de plantão)', 'Cobertura', 'V7.2: Trauma cirúrgico e NE deixam de ser cobertura (passam à carteira dela).', 'Ter 11:15–12:00; Ter 14:15–15:00', '1 h 30/semana', 'daily', ARRAY[2]::smallint[], NULL, false, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (16, 'camila', 'Cobertura e apoio do dia no plantão', 'Início do plantão (7h): ler a fila preparada por Mara Rubia, a lista de alertas e as passagens. Depois, conforme o dia: (a) dia útil sem titular – assumir a área sem titular com ficha/busca ativa COMPLETA: terça, CTIs 1–3; quarta, CTIs 1–3 e alertas das áreas da Rosângela (libera a Mara Rubia); quinta, área da Rosângela; (b) dia com as titulares – apoiar quem estiver no setor (pendências de fichas, admissões, gatilhos das enfermarias com a Mara Rubia, prevalência nos dias 10 e 25); (c) fim de semana – vigilância crítica: admissões, dispositivos e alertas de todas as áreas críticas, inclusão provisória de precaução e passagem para segunda. Encaminhar suspeitas à validação (CTIs: Cristiane; demais: Mara Rubia).', 'Em cada plantão (12x60, 7h–19h)', 'high', 'Mara Rubia (CTIs: Cristiane)', 'Técnica titular do setor / Mara Rubia', 'Cobertura', 'NOVO V7.2: Camila em 12x60 deixa de ter carteira fixa e vira técnica plantonista.', 'Plantão H0–H1; Plantão H3–H5; Plantão H7–H9', '5 h por plantão', 'daily', NULL, NULL, true, '{}'::text[]),
    (17, 'camila', 'Apoio à vigilância – Trauma clínico', 'Em todo plantão, com a Rosângela (titular): revisar os leitos do Trauma clínico – admissões, dispositivos com datas de inserção e retirada, exames, antimicrobianos e critérios de vigilância; atualizar o IRASControl e deixar passagem escrita à titular. Nos dias sem a Rosângela (quarta, quinta e fim de semana), fazer a busca ativa completa do Trauma clínico.', 'Em cada plantão', 'high', 'Mara Rubia', 'Rosângela (titular)', 'Carteira', 'NOVO V7.2: apoio fixo ao Trauma clínico (setor de maior uso de dispositivos por leito).', 'Plantão H1–H3', '2 h por plantão', 'daily', NULL, NULL, true, ARRAY['Trauma Clínico']::text[]),
    (18, 'camila', 'Auditoria de processos no leito – Trauma clínico', 'Checklist padronizado à beira do leito, aplicado a todos os pacientes com dispositivo presentes no momento da auditoria, conforme protocolos institucionais: bundle de cateter venoso central (inserção, manutenção, curativo e data), prevenção de pneumonia associada à ventilação (cabeceira, higiene oral, circuito), sonda vesical (sistema fechado, posição da bolsa, fixação), identificação e datas dos dispositivos, curativos, precauções e coleta de hemocultura/swab quando observada. Registrar não conformidade com responsável do setor e evidência esperada; devolutiva ao enfermeiro do setor no mesmo dia.', 'Em cada plantão (no mínimo semanal)', 'normal', 'Mara Rubia', 'Rosângela', 'Carteira', 'V7.2: sai da Rosângela; frequência passa a cada plantão.', 'Plantão H6–H7', '1 h por plantão', 'daily', NULL, NULL, true, ARRAY['Trauma Clínico']::text[]),
    (19, 'camila', 'Auditorias rotativas – enfermarias, Emergência pediátrica e Centro cirúrgico', 'Processos no leito e higiene das mãos em rodízio pelos plantões: Clínica Médica, Enfermaria pediátrica, Clínicas Cirúrgicas 1 e 2 e Emergência pediátrica – processos e higiene das mãos quinzenais (alternados); Centro cirúrgico – higiene das mãos mensal. Mara Rubia indica na fila o setor do plantão. Sessão de observação direta de 20 minutos (±10), pelos 5 momentos da OMS: registrar categoria profissional, oportunidade, indicação e ação (fricção, lavagem ou não realizada), sem identificação nominal. Processos: checklist padronizado nos pacientes com dispositivo, incluindo curativos e sinais de ISC.', 'Rodízio pelos plantões: enfermarias e EP quinzenal; centro cirúrgico mensal', 'normal', 'Mara Rubia', 'Mara Rubia', 'Auditoria', 'V7.2: auditorias das enfermarias e da Emergência pediátrica concentradas na Camila (as titulares saíram dessas áreas).', 'Plantão H9–H10', '1 h por plantão', 'daily', NULL, NULL, true, ARRAY['Clínica Médica','Enfermaria Pediátrica','Clínica Cirúrgica 1','Clínica Cirúrgica 2','Emergência Pediátrica','Centro Cirúrgico']::text[]),
    (20, 'camila', 'Auditoria de estrutura e insumos – Trauma, UPO, Nova emergência e PCR', 'Transversal – estrutura. Em cada plantão, um setor em rodízio: leitos, pontos de higiene das mãos, dispensers, insumos para os bundles, EPI, sinalização de precaução e fluxo limpo/sujo. Registrar risco, responsável e prazo e enviar à Cristiane, que consolida e valida.', 'Em cada plantão (rodízio)', 'normal', 'Cristiane (risco imediato: Mara Rubia)', 'Rosângela', 'Transversal', 'V7.2: Camila audita a estrutura do trauma e da emergência adulto; a consolidação passa à Cristiane.', 'Plantão H10–H11', '1 h por plantão', 'daily', NULL, NULL, true, ARRAY['Trauma Clínico','Trauma Cirúrgico','UPO','Nova Emergência','PCR']::text[]),
    (21, 'camila', 'Auditoria de higiene das mãos na troca de plantão', '18h–18h40: sessão de 20 min (±10) numa área crítica (prioridade: setor sem sessão na semana), alcançando o fim do turno diurno e a chegada da equipe noturna. Sessão de observação direta de 20 minutos (±10), pelos 5 momentos da OMS: registrar categoria profissional, oportunidade, indicação e ação (fricção, lavagem ou não realizada), sem identificação nominal. 18h40–19h: passagem escrita para a técnica do dia seguinte e para Mara Rubia; formulário à Rosângela.', 'Em cada plantão', 'normal', 'Mara Rubia', 'Cristiane (plantão)', 'Auditoria', 'NOVO V7.2: o plantão de 12 h permite medir a adesão na troca de turno.', 'Plantão H11–H12', '1 h por plantão', 'daily', NULL, NULL, true, '{}'::text[]),
    (22, 'camila', 'Apoio à prevalência pontual das enfermarias (dias 10 e 25)', 'Se o plantão cair no dia 10 ou 25, apoiar Mara Rubia no levantamento de prevalência e incidência das enfermarias (substitui as auditorias rotativas e parte do bloco de apoio do dia). Registrar a data real.', 'Dias 10 e 25, se de plantão', 'high', 'Mara Rubia', 'Técnica presente no dia', 'Carteira', 'V7.2: prevalência coordenada pela Mara Rubia.', 'Sem bloco fixo', 'Dias 10 e 25 (se de plantão): 3 h', 'daily', NULL, ARRAY[10,25]::smallint[], true, ARRAY['Clínica Médica','Enfermaria Pediátrica','Clínica Cirúrgica 1','Clínica Cirúrgica 2']::text[]),
    (23, 'mara', 'Validar casos e registros epidemiológicos', 'Validar diariamente, por prioridade, as suspeitas e registros do trauma e da emergência adulto (Rosângela e Camila), das enfermarias e da Emergência pediátrica. CTIs: a Cristiane valida nos plantões; Mara Rubia valida só as urgências entre plantões (ex.: necessidade de precaução ou comunicação imediata). Quando a Camila estiver de plantão na quarta, o bloco de cobertura vira validação.', 'Diária', 'high', 'Lucas Lemos', 'Cristiane (nos plantões)', 'Validação', 'V7.2: CTIs passam à validação da Cristiane; enfermarias e EP entram na carteira da própria Mara Rubia.', 'Seg 13:00–14:00; Seg 15:30–16:00; Ter 10:15–12:00; Qua 13:00–14:00; Qui 10:15–12:00; Sex 11:00–12:00; Sex 15:00–16:00', '8 h/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, '{}'::text[]),
    (24, 'mara', 'Vigilância por gatilhos – Clínica Médica, Enfermaria pediátrica e Clínicas Cirúrgicas 1 e 2', 'Revisar diariamente as quatro enfermarias (274 leitos) pela lista de gatilhos: alerta microbiológico, dispositivo invasivo, antimicrobiano, readmissão, precaução e suspeita clínica. Não é ronda leito a leito. Sinais de ISC nas Clínicas Cirúrgicas vão à fila de ISC da Cristiane. Registrar no IRASControl; a Camila apoia nos plantões conforme a fila.', 'Diária', 'high', 'Lucas Lemos (casos confirmados)', 'Camila (plantão); Cristiane (plantão)', 'Carteira', 'NOVO V7.2: as quatro enfermarias saem das técnicas e passam à enfermeira.', 'Seg 09:40–11:10; Ter 08:00–09:30; Qua 09:00–10:30; Qui 08:00–09:30; Sex 08:00–09:30', '7 h 30/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, ARRAY['Clínica Médica','Enfermaria Pediátrica','Clínica Cirúrgica 1','Clínica Cirúrgica 2']::text[]),
    (25, 'mara', 'Vigilância – Emergência pediátrica', 'Triagem por risco dos 10 leitos: alertas, dispositivos, microbiologia, precauções e suspeitas clínicas; atualizar o IRASControl. Integrar com a Enfermaria pediátrica (transferências).', 'Diária', 'high', 'Lucas Lemos (casos confirmados)', 'Camila (plantão)', 'Carteira', 'NOVO V7.2: sai da Rosângela.', 'Seg 11:10–12:00; Ter 09:30–10:15; Qua 10:30–11:00; Qui 09:30–10:15; Sex 09:30–10:15', '3 h 35/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, ARRAY['Emergência Pediátrica']::text[]),
    (26, 'mara', 'Auditoria de estrutura e insumos – enfermarias e Emergência pediátrica', 'Uma auditoria por semana em rodízio (CM, Pediatria, CC1, CC2 e Emergência pediátrica): leitos, pontos de higiene das mãos, dispensers, insumos, EPI, sinalização de precaução, fluxo limpo/sujo. Registrar risco, responsável e prazo; enviar à Cristiane para consolidação mensal.', 'Semanal, quinta-feira (rodízio)', 'normal', 'Cristiane', 'Camila (plantão)', 'Auditoria', 'NOVO V7.2: estrutura das enfermarias e da EP com a enfermeira.', 'Qui 15:30–16:30', '1 h/semana', 'daily', ARRAY[4]::smallint[], NULL, false, ARRAY['Clínica Médica','Enfermaria Pediátrica','Clínica Cirúrgica 1','Clínica Cirúrgica 2','Emergência Pediátrica']::text[]),
    (27, 'mara', 'Prevalência pontual e incidência – enfermarias', 'Dias 10 e 25 (ou o dia útil seguinte, se cair no fim de semana): levantamento de prevalência e de casos novos nas quatro enfermarias (e na Ortopedia, quando localizada). Mara Rubia coordena e executa; apoio da Camila, se de plantão, ou da técnica presente por 1 h 30 à tarde (só alertas críticos no período). Registrar a data real; análise e BI.', 'Dias 10 e 25 de cada mês', 'high', 'Lucas Lemos', 'Camila (plantão) / técnica presente', 'Carteira', 'V7.2: os três cartões de prevalência das técnicas viram um, coordenado pela Mara Rubia.', 'Sem bloco fixo', 'Dias 10 e 25: 4 h', 'daily', NULL, ARRAY[10,25]::smallint[], false, ARRAY['Clínica Médica','Enfermaria Pediátrica','Clínica Cirúrgica 1','Clínica Cirúrgica 2']::text[]),
    (28, 'mara', 'Cobertura de alertas críticos (quarta, sem plantão da Camila) – CTIs, trauma e emergência adulto', 'Quarta-feira sem técnica fixa: se a Camila não estiver de plantão (2 em cada 3 semanas), revisar SOMENTE a lista de alertas críticos dos CTIs 1–3 e das áreas da Rosângela, registrar conduta e deixar passagem escrita para Danúbia e Rosângela. Se a Camila estiver de plantão, o bloco vira validação.', 'Quarta-feira (2 em cada 3 semanas)', 'high', 'Lucas Lemos', 'Camila (se de plantão)', 'Cobertura', 'NOVO V7.2: a quarta perde a técnica fixa (Camila em 12x60); decisão da coordenação de manter a escala das demais.', 'Qua 11:00–12:00; Qua 14:00–14:30', '1 h 30/semana', 'daily', ARRAY[3]::smallint[], NULL, false, ARRAY['CTI 1','CTI 2','CTI 3','Trauma Clínico','Trauma Clínico Externo','UPO','Trauma Cirúrgico','Nova Emergência','PCR']::text[]),
    (29, 'mara', 'Triagem microbiológica mínima e inclusão provisória no mapa', 'Segunda e quarta, sem Valéria: revisar os resultados críticos lançados pelo administrativo, indicar a precaução empírica conforme protocolo institucional e incluir o paciente no mapa como ''provisório – pendente de revisão microbiológica''. Não substitui a análise da bióloga.', 'Segunda e quarta', 'high', 'Lucas Lemos', 'Cristiane ou Camila (se de plantão)', 'Cobertura', 'NOVO: consequência da presença de Valéria apenas terça, quinta e sexta.', 'Seg 08:40–09:40; Qua 08:00–09:00', '2 h/semana', 'daily', ARRAY[1,3]::smallint[], NULL, false, '{}'::text[]),
    (30, 'mara', 'Apresentação semanal dos dados internos e priorização', 'Com Danúbia e Rosângela (e a Camila, se de plantão) e o coordenador: apresentar os dados internos da semana, revisar a passagem do fim de semana (plantão da Camila/Cristiane) e as pendências críticas, confirmar a matriz de cobertura e o plantão da Camila na quarta, definir auditorias da semana e registrar responsáveis e prazos.', 'Semanal, segunda-feira', 'high', 'Lucas Lemos', 'Cristiane', 'Governança', 'Ajustado: incorpora a apresentação semanal dos dados internos (prática do setor).', 'Seg 08:00–08:40', '40 min/semana', 'daily', ARRAY[1]::smallint[], NULL, false, '{}'::text[]),
    (31, 'mara', 'Treinamento semanal da equipe do SCIH', 'Toda segunda-feira, com as quatro técnicas presentes: educação continuada interna com rodízio de apresentadores (técnicas, enfermeiros, bióloga, médica/infectologista), sobre prevenção de infecções e desafios recentes. Registrar tema, presença e avaliação.', 'Semanal, segunda-feira', 'normal', 'Lucas Lemos', 'Cristiane', 'Treinamento', 'NOVO no Kanban: atividade vigente do setor.', 'Seg 16:00–16:45', '45 min/semana', 'daily', ARRAY[1]::smallint[], NULL, false, '{}'::text[]),
    (32, 'mara', 'Fechamento semanal da equipe', 'Na sexta, com Danúbia e Rosângela (e a Camila, se de plantão): conferir lacunas da semana, pendências vencidas, cobertura das auditorias, passagens dos dias com técnica única e da quarta, e a programação da semana seguinte (plantões da Camila e da Cristiane).', 'Semanal, sexta-feira', 'normal', 'Lucas Lemos', 'Cristiane', 'Governança', 'V7.2: sexta passa a ter duas técnicas fixas.', 'Sex 16:00–16:30', '30 min/semana', 'daily', ARRAY[5]::smallint[], NULL, false, '{}'::text[]),
    (33, 'mara', 'Preparar as filas dos plantões (Cristiane e Camila)', 'Antes de cada plantão: Cristiane – casos dos CTIs para validação, suspeitas de ISC e pendências críticas; Camila – área sem titular do dia (ou apoio), setor das auditorias rotativas, setor de estrutura e pendências das enfermarias. Conferir o ciclo 12x60 da Camila e a escala da Cristiane publicados no mês.', 'A cada plantão agendado', 'high', 'Lucas Lemos', 'Administrativo mantém a lista', 'Governança', 'V7.2: inclui a fila do plantão técnico da Camila.', 'Seg 15:00–15:30; Qua 16:00–16:30', '1 h/semana', 'daily', ARRAY[1,3]::smallint[], NULL, false, '{}'::text[]),
    (34, 'mara', 'Gestão das não conformidades assistenciais', 'Validar risco, definir setor responsável e prazo, acompanhar evidência, reincidência e pendências. Consolidar semanalmente as auditorias de processos enviadas pelas técnicas (sexta; no fluxo atual, quinta). Encaminhar ações intersetoriais para encerramento pelo coordenador. As não conformidades de limpeza ficam com Oseas.', 'Semanal', 'high', 'Lucas Lemos', 'Cristiane', 'Governança', 'Escopo ajustado: limpeza sai para Oseas; consolidação das auditorias de processos passa de quinta para sexta (quinta tem uma só técnica).', 'Seg 14:00–15:00; Sex 14:00–15:00', '2 h/semana', 'weekly', NULL, NULL, false, '{}'::text[]),
    (35, 'mara', 'Fluxo de bloqueio de porta de entrada', 'Aplicar o POP de bloqueio de entrada: as técnicas identificam nas admissões os pacientes que atendem aos critérios; Mara Rubia confere coleta de swab e precaução, e Valéria confere os resultados. Análise semanal na sexta.', 'Diária (identificação); análise semanal na sexta', 'high', 'Lucas Lemos', 'Cristiane', 'Precaução', 'NOVO no Kanban: atividade vigente do setor.', 'Sex 10:15–11:00', '45 min/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, '{}'::text[]),
    (36, 'mara', 'Fluxo de profilaxia de meningite', 'Acionar o protocolo institucional de meningite quando houver caso suspeito, conferir a indicação e a aplicação da profilaxia dos contatos e registrar o tempo entre notificação e profilaxia. Monitoramento semanal dos casos abertos.', 'Por evento; monitoramento semanal', 'high', 'Lucas Lemos', 'Cristiane (se de plantão)', 'Precaução', 'NOVO no Kanban: atividade vigente do setor.', 'Sem bloco fixo', 'Por evento: imediato; monitoramento 15 min/semana', 'weekly', NULL, NULL, false, '{}'::text[]),
    (37, 'mara', 'Investigação de surtos e relatório mensal de controle', 'Investigar possível caso ou surto assim que detectado (com Valéria e Cristiane), documentar detecção, investigação e medidas de controle e consolidar o relatório mensal de controle de surtos.', 'Por evento; relatório mensal até o 20º dia útil', 'high', 'Lucas Lemos', 'Cristiane', 'Governança', 'NOVO no Kanban: saiu de Lucas/Oseas (Oseas agora é dedicado à limpeza).', 'Sex 13:00–14:00', '1 h/semana', 'monthly', NULL, NULL, false, '{}'::text[]),
    (38, 'mara', 'Preparar casos para o round da infectologista', 'Montar a lista de casos complexos para o round da infectologista e para parecer da médica da SCIH, participar do round e registrar condutas e pareceres respondidos.', 'Terça e quinta', 'high', 'Lucas Lemos', 'Cristiane (se de plantão)', 'Validação', 'NOVO no Kanban: atividade vigente do setor.', 'Ter 13:00–14:00; Qui 13:00–14:00', '2 h/semana', 'daily', ARRAY[2,4]::smallint[], NULL, false, '{}'::text[]),
    (39, 'mara', 'Programa de coleta e controle da água', 'Organizar a coleta conforme plano amostral, conferir resultado, avaliar risco com as áreas técnicas e acompanhar providências e evidências. Oseas apoia a logística.', 'Mensal (1ª semana) e por evento', 'high', 'Lucas Lemos', 'Oseas Macedo', 'Ambiental', 'Mantido. Pragas e caixa d''água passam a ter Oseas como responsável.', 'Sem bloco fixo', '1ª semana: 3 h', 'monthly', NULL, ARRAY[1,2,3,4,5,6,7]::smallint[], false, '{}'::text[]),
    (40, 'mara', 'Fechamento mensal dos indicadores (gerais e Anvisa – IRAS)', 'Enviar a versão preliminar dos indicadores gerais no 1º dia útil (prazo vigente do setor). Consolidar numeradores, denominadores, paciente-dia e dispositivo-dia; revisar completude e consistência; devolver correções; preparar a notificação de IRAS para aprovação até o prazo interno (13º dia corrido).', 'Mensal: 1º dia útil (preliminar); 1º ao 6º dia útil (fechamento)', 'high', 'Lucas Lemos', 'Cristiane', 'Governança', 'Ajustado ao prazo vigente do setor (1º dia útil), com fechamento validado em seguida.', 'Ter 14:00–15:30; Qua 14:30–16:00; Qui 14:00–15:30', '4 h 30/semana', 'monthly', NULL, NULL, false, '{}'::text[]),
    (41, 'mara', 'Validar DDD e taxas do BI', 'Conferir os dados preparados pelo administrativo (consumo de antimicrobianos, paciente-dia e taxas), validar o cálculo e liberar para envio pelo coordenador.', 'Mensal: DDD até o 4º dia útil; BI até o 9º dia útil', 'high', 'Lucas Lemos', 'Cristiane', 'Governança', 'NOVO: DDD saiu de Lucas/Oseas (Oseas agora é dedicado à limpeza). PLACON permanece com Valéria.', 'Sem bloco fixo', 'Mensal: 1 h (DDD) + 30 min (BI)', 'monthly', NULL, NULL, false, '{}'::text[]),
    (42, 'mara', 'Treinamentos assistenciais em horário diurno', 'Executar os treinamentos diurnos do calendário aprovado, registrar conteúdo, público e avaliação e verificar aplicação no processo.', 'Conforme calendário', 'normal', 'Cristiane (dona do calendário)', 'Cristiane', 'Treinamento', 'ALTERADO: Mara Rubia executa; o planejamento do calendário passa para Cristiane.', 'Ter 15:30–16:30', '1 h/semana', 'weekly', NULL, NULL, false, '{}'::text[]),
    (43, 'cristiane', 'Executar a fila priorizada do plantão', 'Revisar casos críticos, precauções complexas, eventos agudos e pendências priorizadas por Mara Rubia (exceto CTIs, que têm bloco próprio). No fim de semana, a triagem crítica junto com a Camila, se ambas de plantão. Registrar decisões e fazer passagem formal para Mara Rubia.', 'Em cada plantão', 'high', 'Lucas Lemos', 'Mara Rubia', 'Validação', 'V7.2: a triagem das enfermarias sai do plantão (enfermarias passam à Mara Rubia); a fila fica com 1 h.', 'Plantão H0–H1', '1 h por plantão', 'daily', NULL, NULL, true, '{}'::text[]),
    (44, 'cristiane', 'Vigilância dos CTIs – revisão de critérios e validação dos casos', 'Nos três CTIs, a cada plantão: revisar as fichas e o IRASControl preenchidos pela Danúbia (e pela Camila nos plantões dela), aplicar os critérios diagnósticos nacionais de IRAS da Anvisa às suspeitas (IPCS, PAV, ITU-AC), conferir dispositivos e datas à beira do leito, discutir com a equipe médica quando necessário e validar ou descartar. Passagem formal: correções à Danúbia; pendências a Mara Rubia.', 'Em cada plantão', 'high', 'Lucas Lemos', 'Mara Rubia (urgências entre plantões)', 'Validação', 'NOVO V7.2: a enfermeira plantonista assume a vigilância dos CTIs, reduzindo a carga de validação da Mara Rubia.', 'Plantão H1–H4', '3 h por plantão', 'daily', NULL, NULL, true, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (45, 'cristiane', 'Coordenação técnica da vigilância de ISC', 'Validar a lista de procedimentos elegíveis e o denominador; validar a Ficha NISS e os dados de cirurgias contaminadas; revisar seguimento, perdas e casos suspeitos vindos da busca telefônica e das enfermarias cirúrgicas; classificar desfechos com apoio médico quando necessário e preparar o fechamento mensal de ISC.', 'Em cada plantão; fechamento mensal', 'high', 'Lucas Lemos', 'Mara Rubia', 'Transversal', 'Ampliado: passa a ser a dona do processo de ISC (antes só revisava).', 'Plantão H4–H6', '2 h por plantão', 'daily', NULL, NULL, true, ARRAY['Centro Cirúrgico','Clínica Cirúrgica 1','Clínica Cirúrgica 2']::text[]),
    (46, 'cristiane', 'Auditoria de estrutura e insumos – CTI 1, CTI 2 e CTI 3', 'Em cada plantão, um CTI em rodízio: leitos, pontos de higiene das mãos, dispensers, insumos para os bundles (CVC, PAV, SVD), EPI, sinalização de precaução, fluxo limpo/sujo e casos de precaução complexa; abrir plano de ação com dono, prazo e evidência. No fim do mês, consolidar as auditorias de estrutura do hospital (CTIs; enfermarias e EP pela Mara Rubia; trauma e emergência adulto pela Camila) e validar os achados de alto risco.', 'Em cada plantão (rodízio entre os três CTIs); consolidação mensal', 'high', 'Lucas Lemos', 'Mara Rubia', 'Auditoria', 'V7.2: estrutura dos CTIs com a Cristiane; consolidação de estrutura sai da Camila.', 'Plantão H7–H8', '1 h por plantão', 'daily', NULL, NULL, true, ARRAY['CTI 1','CTI 2','CTI 3']::text[]),
    (47, 'cristiane', 'Auditoria de higiene das mãos nos plantões', 'Uma sessão de observação por plantão, priorizando os CTIs e alternando com o trauma e a emergência, para medir a adesão das equipes de plantão. Sessão de observação direta de 20 minutos (±10), pelos 5 momentos da OMS: registrar categoria profissional, oportunidade, indicação e ação (fricção, lavagem ou não realizada), sem identificação nominal. Entregar a Rosângela para consolidação.', '1 sessão por plantão', 'normal', 'Mara Rubia', 'Mara Rubia', 'Auditoria', 'NOVO V7.1: higiene das mãos também fora do horário diurno.', 'Plantão H8–H9', '1 h por plantão', 'daily', NULL, NULL, true, '{}'::text[]),
    (48, 'cristiane', 'Planejar o calendário de treinamentos do SCIH', 'Propor o calendário mensal por risco identificado (auditorias, não conformidades, casos), garantindo alcance às equipes de plantão. Enviar para aprovação do coordenador e acompanhar a execução e a avaliação.', 'Mensal', 'normal', 'Lucas Lemos', 'Mara Rubia', 'Treinamento', 'ALTERADO: planejamento transferido de Mara Rubia para reduzir a concentração na rotina.', 'Plantão H10–H11', '1 h por plantão', 'monthly', NULL, NULL, true, '{}'::text[]),
    (49, 'cristiane', 'Treinamento programado no plantão', 'Executar o treinamento previsto e registrar conteúdo, participantes, avaliação e pendências. Não substituir demanda crítica do plantão por atividade eletiva.', 'Conforme calendário', 'normal', 'Mara Rubia', 'Mara Rubia', 'Treinamento', 'Mantido.', 'Plantão H9–H10', '1 h por plantão', 'daily', NULL, NULL, true, '{}'::text[]),
    (50, 'oseas', 'Auditoria de limpeza concorrente e terminal', 'Auditar técnica, sequência, produto, diluição, registro e condição final conforme protocolo institucional. Abrir não conformidade e acompanhar evidência de correção.', 'Diária, por plano de risco', 'high', 'Lucas Lemos', 'Mara Rubia apenas em risco crítico', 'Limpeza', 'Mantido.', 'Seg 08:00–08:30; Seg 08:30–10:30; Seg 13:00–14:30; Ter 08:00–08:30; Ter 08:30–10:30; Ter 13:00–14:30; Qua 08:00–08:30; Qua 08:30–10:30; Qua 13:00–14:30; Qui 08:00–08:30; Qui 08:30–10:30; Qui 13:00–14:30; Sex 08:00–08:30; Sex 08:30–10:30; Sex 13:00–14:30', '20 h/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, '{}'::text[]),
    (51, 'oseas', 'Fiscalização de dispensers, lixeiras e ambiente', 'Verificar disponibilidade, integridade, identificação, resíduos e condições higiênico-sanitárias. Registrar setor, risco, responsável e prazo.', 'Diária, por rota planejada', 'high', 'Lucas Lemos', 'Mara Rubia apenas em risco crítico', 'Limpeza', 'Mantido.', 'Seg 10:30–12:00; Ter 10:30–12:00; Qua 10:30–12:00; Qui 10:30–12:00; Sex 10:30–12:00', '7 h 30/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, '{}'::text[]),
    (52, 'oseas', 'Treinamento da equipe de higiene e limpeza', 'Treinar conforme falhas e riscos observados, registrar participantes e avaliar execução no posto de trabalho após o treinamento.', 'Semanal ou conforme calendário', 'normal', 'Lucas Lemos', 'Mara Rubia', 'Treinamento', 'Mantido.', 'Seg 14:30–15:30; Qua 14:30–15:30', '2 h/semana', 'weekly', NULL, NULL, false, '{}'::text[]),
    (53, 'oseas', 'Gerir não conformidades de higiene e limpeza', 'Cobrar evidências, reinspecionar achados críticos, medir reincidência e encaminhar bloqueios ao coordenador. Oseas valida o eixo de limpeza.', 'Semanal', 'high', 'Lucas Lemos', 'Mara Rubia', 'Limpeza', 'Mantido; Oseas passa a validar o próprio eixo.', 'Seg 15:30–16:30; Ter 14:30–15:30; Ter 15:30–16:30; Qua 15:30–16:30; Qui 14:30–15:30; Qui 15:30–16:30; Sex 14:30–15:30; Sex 15:30–16:30', '8 h/semana', 'weekly', NULL, NULL, false, '{}'::text[]),
    (54, 'oseas', 'Controle de pragas e limpeza da caixa d''água', 'Responsável por solicitar e acompanhar o controle de pragas (solicitação até o 5º dia útil) e planejar mensalmente a limpeza dos reservatórios, executada a cada 5 meses; conferir certificados e evidências, registrar riscos e cobrar as áreas executoras.', 'Pragas: mensal (até o 5º dia útil); caixa d''água: planejamento mensal e limpeza a cada 5 meses', 'normal', 'Lucas Lemos', 'Mara Rubia', 'Ambiental', 'ALTERADO: pragas saem de Mara Rubia e caixa d''água sai de Lucas; Oseas passa a ser o responsável, por afinidade com a interface hotelaria/manutenção.', 'Sem bloco fixo', '1ª semana: 1 h; caixa d''água: 2 h a cada 5 meses', 'monthly', NULL, ARRAY[1,2,3,4,5,6,7]::smallint[], false, '{}'::text[]),
    (55, 'oseas', 'Apoio logístico à coleta de água', 'Apoiar a coleta conforme o plano de Mara Rubia (acesso aos pontos, contato com manutenção e registro de evidências).', 'Mensal (1ª semana) e por evento', 'normal', 'Mara Rubia', 'Mara Rubia', 'Ambiental', 'Mantido.', 'Sem bloco fixo', '1ª semana: 2 h', 'monthly', NULL, ARRAY[1,2,3,4,5,6,7]::smallint[], false, '{}'::text[]),
    (56, 'valeria', 'Revisão microbiológica e alertas', 'Revisar os resultados liberados, inclusive os de segunda e quarta (dias de ausência) e do fim de semana; classificar alertas, verificar resistência relevante, confirmar ou ajustar as inclusões provisórias feitas por Mara Rubia e comunicar achados críticos ao enfermeiro.', 'Terça, quinta e sexta', 'high', 'Mara Rubia', 'Mara Rubia faz triagem mínima (seg e qua)', 'Microbiologia', 'ALTERADO: recorrência corrigida para os dias reais de presença.', 'Ter 08:00–10:00; Ter 11:30–12:00; Ter 13:00–14:00; Qui 08:00–10:00; Qui 11:30–12:00; Qui 13:00–14:00; Sex 08:00–10:00; Sex 11:30–12:00', '9 h 30/semana', 'daily', ARRAY[2,4,5]::smallint[], NULL, false, '{}'::text[]),
    (57, 'valeria', 'Atualizar mapa de precauções', 'Conciliar microbiologia, suspeita clínica, síndrome, via de transmissão e protocolo institucional. Na sexta, publicar a versão que vale para o fim de semana. Sinalizar divergências para conferência no leito e validação do enfermeiro.', 'Terça, quinta e sexta', 'high', 'Mara Rubia', 'Mara Rubia (inclusão provisória seg e qua)', 'Microbiologia', 'ALTERADO: backup deixa de ser Rosângela (técnica confere no leito, não atualiza o mapa).', 'Ter 10:00–11:30; Ter 16:00–16:30; Qui 10:00–11:30; Qui 16:00–16:30; Sex 10:00–11:30; Sex 16:00–16:30', '6 h/semana', 'daily', ARRAY[2,4,5]::smallint[], NULL, false, '{}'::text[]),
    (58, 'valeria', 'Lançar e enviar o PLACON RJ', 'Lançar e enviar mensalmente os dados do PLACON RJ, com apoio do administrativo para a digitação; guardar comprovante de envio.', 'Mensal (até o 10º dia útil)', 'high', 'Mara Rubia; Lucas Lemos aprova', 'Mara Rubia', 'Microbiologia', 'NOVO no Kanban: mantém a responsável atual (Valéria).', 'Sex 13:00–15:00', '2 h/semana', 'monthly', NULL, NULL, false, '{}'::text[]),
    (59, 'valeria', 'Lançar dados de microrganismos e resistência (Anvisa)', 'Lançar os dados de microrganismos e perfil de resistência da notificação mensal à Anvisa. Prazo interno: 13º dia corrido; externo: 15º dia após o mês de vigilância (NT Anvisa nº 02/2026).', 'Mensal (até o 13º dia corrido)', 'high', 'Mara Rubia; Lucas Lemos envia', 'Mara Rubia', 'Microbiologia', 'NOVO no Kanban: sai de Oseas/Valéria e fica com Valéria; prazo corrigido.', 'Sex 15:00–16:00', '1 h/semana', 'monthly', NULL, NULL, false, '{}'::text[]),
    (60, 'valeria', 'Painel microbiológico mensal', 'Consolidar perfil microbiológico, resistência, setores e materiais do mês para compor o fechamento dos indicadores.', 'Mensal (até o 6º dia útil)', 'normal', 'Mara Rubia e Lucas Lemos', 'Enfermeiro treinado mantém a fila, sem substituir a análise', 'Microbiologia', 'Separado do relatório analítico.', 'Ter 14:00–16:00; Qui 14:00–16:00', '4 h/semana', 'monthly', NULL, NULL, false, '{}'::text[]),
    (61, 'valeria', 'Relatório microbiológico analítico', 'Destacar tendências, limitações, alertas e ações necessárias para a CCIH.', 'Semestral (junho e dezembro), com preparação mensal', 'normal', 'Mara Rubia e Lucas Lemos', '—', 'Microbiologia', 'Alinhado ao documento do setor: relatório final em junho e dezembro.', 'Sem bloco fixo', 'Jun e dez: 8 h (4 blocos)', 'monthly', NULL, NULL, false, '{}'::text[]),
    (62, 'administrativo', 'Atualizar altas e movimentações', 'Conferir e lançar altas e movimentações nas bases definidas, manter fila de pendências e comunicar inconsistências. Não interpretar nem validar casos.', 'Diária', 'high', 'Mara Rubia', 'Backup administrativo a designar', 'Dados', 'Mantido.', 'Seg 08:00–09:30; Ter 08:00–09:30; Qua 08:00–09:30; Qui 08:00–09:30; Sex 08:00–09:30', '7 h 30/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, '{}'::text[]),
    (63, 'administrativo', 'Lançamento operacional de exames e lista de alertas', 'Registrar os resultados no sistema em uso (o documento do setor cita Epimed; a proposta cita IRASControl – confirmar) e gerar, até as 10h30, a lista de resultados críticos do dia: para Valéria (terça, quinta e sexta) e para Mara Rubia (segunda e quarta). Não classificar microrganismo nem decidir precaução.', 'Diária', 'high', 'Valéria e Mara Rubia', 'Backup administrativo a designar', 'Dados', 'Destinatário do alerta ajustado aos dias da Valéria.', 'Seg 09:30–10:30; Seg 16:30–17:00; Ter 09:30–10:30; Ter 16:30–17:00; Qua 09:30–10:30; Qua 16:30–17:00; Qui 09:30–10:30; Qui 16:30–17:00; Sex 09:30–10:30; Sex 16:30–17:00', '7 h 30/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, '{}'::text[]),
    (64, 'administrativo', 'Organizar planilha de cirurgias e aplicar filtro de elegibilidade', 'Registrar as cirurgias (uma linha por procedimento), conferir campos obrigatórios, remover duplicidades e marcar as elegíveis pela LISTA APROVADA de procedimentos (tarefa mecânica, sem interpretação). Gerar a fila de seguimento com as datas de contato.', 'Semanal (mínimo)', 'high', 'Cristiane', 'Backup administrativo a designar', 'ISC', 'ALTERADO: o filtro de elegibilidade sai da Camila e vem para cá, sob validação da Cristiane.', 'Seg 13:00–13:30; Ter 13:00–13:30; Qua 13:00–13:30; Qui 13:00–13:30; Sex 13:00–13:30', '2 h 30/semana', 'weekly', NULL, NULL, false, ARRAY['Centro Cirúrgico']::text[]),
    (65, 'administrativo', 'Lançar a Ficha NISS', 'Lançar diariamente as fichas NISS (notificação de infecção de sítio cirúrgico) na planilha e preparar o consolidado mensal para validação da Cristiane.', 'Diária; fechamento até o 5º dia útil', 'high', 'Cristiane', 'Cristiane', 'ISC', 'NOVO no Kanban: saiu de Mara Rubia/Thaciane.', 'Seg 13:30–14:00; Ter 13:30–14:00; Qua 13:30–14:00; Qui 13:30–14:00; Sex 13:30–14:00', '2 h 30/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, ARRAY['Centro Cirúrgico']::text[]),
    (66, 'administrativo', 'Lançar os dados de cirurgias contaminadas', 'Lançar mensalmente os dados das cirurgias contaminadas a partir da planilha cirúrgica, para correlação com a NISS.', 'Mensal (até o 15º dia útil)', 'normal', 'Cristiane', 'Backup administrativo a designar', 'ISC', 'NOVO no Kanban: saiu de Mara Rubia.', 'Sem bloco fixo', 'Mensal: 1 h', 'monthly', NULL, NULL, false, ARRAY['Centro Cirúrgico']::text[]),
    (67, 'administrativo', 'Busca telefônica pós-alta – executor principal', 'Executar o roteiro aprovado conforme a fila, registrar cada tentativa e resposta e encaminhar sinais de suspeita à fila de ISC. A ligação não confirma ISC. Na V7 o administrativo é o único executor; o volume depende da lista de procedimentos elegíveis.', 'Diária, conforme fila', 'high', 'Cristiane', 'Backup administrativo a designar', 'ISC', 'V7: executor único (o bloco de apoio da técnica foi extinto).', 'Seg 10:30–12:00; Seg 14:00–15:30; Ter 10:30–12:00; Ter 14:00–15:30; Qua 10:30–12:00; Qua 14:00–15:30; Qui 10:30–12:00; Qui 14:00–15:30; Sex 10:30–12:00; Sex 14:00–15:30', '15 h/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, ARRAY['Centro Cirúrgico']::text[]),
    (68, 'administrativo', 'Preparar dados de DDD e das taxas do BI', 'Obter o relatório de consumo de antimicrobianos da farmácia e o paciente-dia, preencher o cálculo do DDD e a planilha de taxas do BI e enviar para validação de Mara Rubia.', 'Mensal: DDD até o 3º dia útil; BI até o 8º dia útil', 'high', 'Mara Rubia', 'Backup administrativo a designar', 'Dados', 'NOVO: preparação operacional do DDD e do BI, antes feita pela coordenação.', 'Sem bloco fixo', 'Mensal: 2 h (DDD) + 1 h (BI)', 'monthly', NULL, NULL, false, '{}'::text[]),
    (69, 'administrativo', 'Controle de documentos, atas, prazos e agenda-mestra', 'Versionar documentos, registrar envio, assinatura, pendência e evidência. Alertar responsáveis antes dos prazos internos e externos. Registrar presença e evidências dos treinamentos.', 'Diária e mensal', 'normal', 'Mara Rubia', 'Backup administrativo a designar', 'Governança', 'Soma o registro de treinamentos.', 'Seg 15:30–16:30; Ter 15:30–16:30; Qua 15:30–16:30; Qui 15:30–16:30; Sex 15:30–16:30', '5 h/semana', 'daily', ARRAY[1,2,3,4,5]::smallint[], NULL, false, '{}'::text[]),
    (70, 'administrativo', 'Redigir a ata da reunião mensal da CCIH', 'Redigir a ata no modelo padrão, coletar assinaturas e entregar ao coordenador a tempo do envio à Qualidade.', 'Mensal, após a reunião', 'normal', 'Lucas Lemos', 'Mara Rubia', 'Governança', 'NOVO no Kanban.', 'Sem bloco fixo', 'Mensal: 1 h', 'monthly', NULL, NULL, false, '{}'::text[]),
    (71, 'lucas', 'Aprovar e assinar produtos do SCIH', 'Revisar produtos validados, aprovar ou devolver para correção e assinar conforme governança institucional. Enviar o DDD até o 5º dia útil. Aprovação do fechamento mensal até o 7º dia útil e nunca após o 12º dia corrido.', 'Mensal e conforme demanda', 'high', 'Coordenação', 'Substituto institucional a formalizar', 'Governança', 'Prazo interno explícito.', 'Sem bloco fixo', 'Mensal: 2 h', 'monthly', NULL, NULL, false, '{}'::text[]),
    (72, 'lucas', 'Enviar a notificação mensal à Anvisa (IRAS e microrganismos/RAM)', 'Enviar pessoalmente ou por profissional formalmente autorizado. Prazo interno: 13º dia corrido. Prazo externo: até o 15º dia após o mês de vigilância (NT GVIMS/GGTES/DIRE3/Anvisa nº 02/2026). O fluxo atual do setor usa ''até o 15º dia útil'' para microrganismos, o que ultrapassa o prazo da nota técnica.', 'Mensal', 'high', 'Coordenação', 'Profissional formalmente autorizado', 'Governança', 'NOVO; prazo de microrganismos corrigido de 15º dia útil para 15º dia corrido.', 'Sem bloco fixo', 'Mensal: 30 min', 'monthly', NULL, NULL, false, '{}'::text[]),
    (73, 'lucas', 'Encerrar ações intersetoriais', 'Cobrar hotelaria, assistência, manutenção, farmácia e demais áreas; aceitar evidência, reabrir quando insuficiente e formalizar encerramento.', 'Semanal', 'high', 'Coordenação', 'Substituto institucional a formalizar', 'Governança', 'Mantido.', 'Sex 14:00–15:00', '1 h/semana', 'weekly', NULL, NULL, false, '{}'::text[]),
    (74, 'lucas', 'Reunião da CCIH e plano de ação do mês', 'Conduzir a reunião com Mara Rubia, Oseas, Cristiane e Valéria (infectologista convidada quando possível), aprovar o plano de ação e o calendário de treinamentos. Atenção: se mantida na 1ª quarta-feira, os indicadores do mês anterior ainda não estarão validados; discutir dados validados ou mover para depois do 7º dia útil. Risco crítico não espera a reunião.', 'Mensal – data do regimento (prática atual: 1ª quarta-feira)', 'high', 'CCIH', 'Substituto institucional a formalizar', 'Governança', 'Ajustado à prática vigente do setor; conflito de data sinalizado.', 'Sem bloco fixo', 'Mensal: 1 h 30 (horário a pactuar)', 'monthly', NULL, NULL, false, '{}'::text[]),
    (75, 'lucas', 'Decidir as pendências da reorganização', 'Registrar à direção a redução definitiva de 4 para 3 técnicas e a passagem da Camila à escala 12x60 (quarta-feira sem técnica fixa em 2 de cada 3 semanas); conciliar os 124 leitos; localizar a Ortopedia; confirmar se o ''trauma cirúrgico externo'' é grupo distinto; confirmar Epimed ou IRASControl; aprovar a lista de procedimentos elegíveis para ISC e a lista de alertas críticos; designar backup administrativo e substituto do coordenador.', 'Até a revisão de 30 dias', 'high', 'CCIH', '—', 'Governança', 'NOVO.', 'Sem bloco fixo', 'Até a revisão de 30 dias', 'once', NULL, NULL, false, '{}'::text[]),
    (76, 'lucas', 'Realizar a divisão mensal da equipe', 'No início do mês, com Mara Rubia e Oseas: revisar carteiras, matriz de cobertura, ciclo 12x60 da Camila, escala dos plantões da Cristiane e ausências previstas (férias, licenças); publicar a divisão e os plantões no quadro e no grupo da equipe.', 'Mensal, início do mês', 'normal', 'Coordenação', 'Mara Rubia', 'Governança', 'NOVO no Kanban: atividade vigente do setor.', 'Sem bloco fixo', 'Mensal: 1 h', 'monthly', NULL, NULL, false, '{}'::text[]),
    (77, 'lucas', 'Enviar o relatório de taxas ao BI', 'Enviar as taxas mensais validadas por Mara Rubia para alimentação do BI.', 'Mensal (até o 10º dia útil)', 'normal', 'Coordenação', 'Mara Rubia', 'Governança', 'Mantido com o coordenador; preparação passa ao administrativo.', 'Sem bloco fixo', 'Mensal: 15 min', 'monthly', NULL, NULL, false, '{}'::text[]),
    (78, 'lucas', 'Enviar a planilha de higiene das mãos à Qualidade', 'Enviar o consolidado mensal de higiene das mãos preparado por Rosângela e validado por Mara Rubia.', 'Mensal (até o 10º dia útil)', 'normal', 'Coordenação', 'Mara Rubia', 'Governança', 'Mantido com o coordenador; consolidação passa a Rosângela.', 'Sem bloco fixo', 'Mensal: 15 min', 'monthly', NULL, NULL, false, '{}'::text[]),
    (79, 'lucas', 'Enviar a ata da reunião mensal à Qualidade', 'Revisar a ata redigida pelo administrativo e enviar à Qualidade.', 'Até o 15º dia útil após a reunião', 'normal', 'Coordenação', 'Mara Rubia', 'Governança', 'Mantido com o coordenador.', 'Sem bloco fixo', 'Mensal: 15 min', 'monthly', NULL, NULL, false, '{}'::text[]),
    (80, 'lucas', 'Coordenar o round da infectologista e os pareceres da médica da SCIH', 'Garantir a agenda do round com a infectologista e a resposta de pareceres pela médica da SCIH, com a lista preparada por Mara Rubia.', 'Terça e quinta (horário a pactuar)', 'high', 'Coordenação', 'Mara Rubia', 'Governança', 'NOVO no Kanban: atividade vigente do setor.', 'Ter 13:00–14:00; Qui 13:00–14:00', '2 h/semana', 'daily', ARRAY[2,4]::smallint[], NULL, false, '{}'::text[]),
    (81, 'lucas', 'Renovar o PCIRAS e coordenar a revisão e exposição dos protocolos', 'Renovar o PCIRAS e manter o cronograma de revisão dos protocolos e fluxos do setor. O setor informa que os principais fluxos não estão expostos e que nem todos os profissionais os conhecem: definir exposição nas unidades e evidência de disseminação junto a Cristiane (treinamentos).', 'Conforme cronograma; PCIRAS com prioridade', 'high', 'CCIH', 'Mara Rubia', 'Governança', 'NOVO no Kanban: pendência citada no documento do setor.', 'Sem bloco fixo', 'Conforme cronograma', 'once', NULL, NULL, false, '{}'::text[])
) AS c(ordem, chave, title, description, quando, priority, validador, backup, tipo, alteracao, horario, tempo_alvo,
       recurrence, dias_semana, dias_mes, no_plantao, setores)
JOIN _v72_usuarios u ON u.chave = c.chave
JOIN _v72_usuarios coord ON coord.chave = 'lucas'
WHERE NOT EXISTS (
  SELECT 1 FROM public.kanban_ccih_tarefas t
  WHERE t.hospital_id = u.hospital_id AND t.versao = 'V7.2' AND t.ordem = c.ordem
);
